// Service worker for the web build.
//
// Deliberately hand-written and small rather than generated by Workbox. The
// only thing it has to do is make the app open without a network, and the
// one thing it must never do is get between the app and Firebase.
//
// It cannot precache the JS bundle by name: Metro hashes the filename on
// every build, and this file is copied verbatim out of public/ with no
// build step to substitute anything in. So instead of a precache list, it
// caches what it sees as it sees it, and versions the cache by name — bump
// CACHE below to invalidate everything at once.
const CACHE = 'dose-v1';

// The app shell. '/' is the static-rendered index; the rest are the route
// documents Expo emits, so a hard refresh on any of them works offline.
const SHELL = [
  '/',
  '/login',
  '/peptides',
  '/supplements',
  '/history',
  '/settings',
  '/manifest.webmanifest',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
];

// The JS bundle is the one thing the app cannot boot without, and its
// filename is hashed per build so SHELL can't name it. Rather than add a
// build step to substitute it in, fetch the shell document and read the
// script tags out of it — whatever index.html is loading right now is by
// definition the current bundle.
async function precacheBundle(cache) {
  try {
    const res = await fetch('/', { cache: 'reload' });
    if (!res.ok) return;
    const html = await res.text();
    const urls = [...html.matchAll(/<(?:script|link)[^>]+(?:src|href)="(\/_expo\/[^"]+)"/g)].map(
      (m) => m[1]
    );
    await Promise.all(urls.map((u) => cache.add(u).catch(() => {})));
  } catch {
    // Offline at install time, or the shell moved. The runtime handler
    // below will pick the bundle up on the next load either way.
  }
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then(async (cache) => {
        // Individually, not addAll: addAll rejects the whole install if any
        // one request 404s, and a missing icon shouldn't cost you the
        // offline shell. Route documents are served extensionless by some
        // hosts and as .html by others, so misses here are expected.
        await Promise.all(SHELL.map((url) => cache.add(url).catch(() => {})));
        await precacheBundle(cache);
      })
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);

  // Anything not served from this origin is Firebase — auth tokens,
  // Firestore listeners, the config endpoint. All of it is live, some of it
  // is authenticated, and a stale reply is worse than no reply. Returning
  // without calling respondWith leaves the request entirely alone.
  if (url.origin !== self.location.origin) return;

  // Navigations: network first, so a deploy is picked up immediately, with
  // the cached document as the offline fallback. Falling back to '/' rather
  // than 404ing means a deep link still opens the app, which then routes
  // client-side to where you asked for.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put(request, copy));
          return response;
        })
        .catch(() => caches.match(request).then((hit) => hit || caches.match('/')))
    );
    return;
  }

  // Everything else same-origin is a hashed, immutable build artefact — the
  // JS bundle, fonts, images. Cache first: if it's there it cannot be
  // stale, because a new build means a new filename.
  event.respondWith(
    caches.match(request).then(
      (hit) =>
        hit ||
        fetch(request).then((response) => {
          if (response.ok && response.type === 'basic') {
            const copy = response.clone();
            caches.open(CACHE).then((cache) => cache.put(request, copy));
          }
          return response;
        })
    )
  );
});
